import assert from "node:assert/strict";
import { test } from "node:test";
import { summarize } from "../src/units.ts";

const why = (text: string, path = "src/a.ts") => summarize(path, text).incomplete;
const digests = (text: string, path = "src/a.ts") =>
  Object.fromEntries(summarize(path, text).units.map((u) => [u.key, u.digest]));

test("a file of plain code, comments and docs is covered whole", () => {
  assert.equal(why("// the total\nexport const total = (a: number) => a + 1;\n"), undefined);
  assert.equal(
    why(
      "/**\n * Adds one.\n * @param a the number\n * @returns one more\n */\nexport function f(a) { return a + 1 }\n",
    ),
    undefined,
  );
  assert.equal(why("// write to ops@example.com\nexport const f = 1;\n"), undefined);
  assert.equal(why("// the client (@acme/client's body.ts)\nexport const f = 1;\n"), undefined);
  assert.equal(why("// eslint-disable-next-line\nexport const f = 1;\n"), undefined);
  assert.equal(why("/* @ts-expect-error: wrong */\nexport const f = 1;\n"), undefined);
  assert.equal(
    why(
      'import { a } from "./a";\nimport type { T } from "./t";\nexport const f = (x: T) => a(x);\n',
    ),
    undefined,
  );
});

test("a generated file of types and docs is whole, and a description edit keeps it so", () => {
  const before = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 */

export interface operations {
    createHold: {
        parameters: {
            header?: {
                /** @description A token that works once. */
                "Turnstile-Token"?: components["parameters"]["TurnstileToken"];
                /** @description The client's name for this hold */
                "Idempotency-Key"?: string;
            };
        };
    };
}
export interface components {
    parameters: {
        /** @example 0x4AAA */
        TurnstileToken: string;
    };
    schemas: {
        /**
         * @description How the hold ended
         * @default open
         * @enum {string}
         */
        HoldState: "open" | "paid";
    };
}
export type $defs = Record<string, never>;
`;
  const after = before.replace(
    "The client's name for this hold */",
    "The client's name for this hold, the same for a retry with the same body */",
  );
  assert.equal(why(before), undefined);
  assert.equal(why(after), undefined);
  assert.deepEqual(digests(after), digests(before));
});

test("the same tokens in another layout keep every digest, and stay whole", () => {
  const a =
    "const marker = () =>\n  process.env.B && process.env.O ? join(process.env.O, '.c') : undefined;\n";
  const b =
    "const marker = () =>\n  process.env.B && process.env.O\n    ? join(process.env.O, '.c')\n    : undefined;\n";
  assert.deepEqual(digests(a), digests(b));
  assert.equal(why(a), undefined);
  assert.equal(why(b), undefined);
});

test("a file with a syntax error is not covered whole", () => {
  assert.match(why("export const f = (;\n") ?? "", /syntax error/);
});

test("a comment a bundler reads is whole where a digest holds it", () => {
  const cases: [string, string][] = [
    ['import { make } from "./make";\nexport const f = /*#__PURE__*/ make();\n', "src/a.ts"],
    ['import { make } from "./make";\nexport const f = /* @__PURE__ */ make();\n', "src/a.ts"],
    ["/* @__NO_SIDE_EFFECTS__ */ export function f() { return 1; }\n", "src/a.ts"],
    ["export const f = (name: string) => import(/* @vite-ignore */ name);\n", "src/a.ts"],
    ["export const f = () => import(/* webpackChunkName: 'x' */ './x');\n", "src/a.ts"],
    ["/** @jsx h */\nexport const f = () => <a />;\n", "src/a.tsx"],
    ["/** @jsxImportSource preact */\nexport const f = () => <a />;\n", "src/a.tsx"],
  ];
  for (const [text, path] of cases) assert.equal(why(text, path), undefined, text);
});

test("a comment a tool reads that no digest holds keeps the file from being whole", () => {
  const cases: [string, string, RegExp][] = [
    [
      "// @vitest-environment jsdom\nexport const f = 1;\n",
      "src/a.test.ts",
      /pragma \(@vitest-environment\)/,
    ],
    ["/** @jest-environment node */\nexport const f = 1;\n", "src/a.test.ts", /pragma/],
    ["// @flow\nexport const f = 1;\n", "src/a.js", /pragma/],
    ["export function f() {\n  return 1; // @refresh reset\n}\n", "src/a.tsx", /pragma/],
    ['/// <reference types="vite/client" />\nexport const f = 1;\n', "src/a.ts", /triple-slash/],
    ["export const f = 1;\n//# sourceMappingURL=a.js.map\n", "src/a.js", /source map/],
    ["/* c8 ignore next */\nexport const f = 1;\n", "src/a.ts", /coverage/],
    ["/* istanbul ignore next */\nexport const f = 1;\n", "src/a.ts", /coverage/],
    // a legal comment: the bundle keeps it, and no digest holds it
    ["/*! Copyright the authors, MIT */\nexport const f = 1;\n", "src/a.ts", /legal/],
    ["/** @license MIT */\nexport const f = 1;\n", "src/a.ts", /legal/],
    ["// @preserve the notice\nexport const f = 1;\n", "src/a.ts", /legal/],
    // a pragma only the file's head holds
    ["export const f = 1;\n/** @jsx h */\nexport const g = () => <a />;\n", "src/a.tsx", /JSX/],
    // an annotation no build text of canon's covers
    ["export const f = /* #__INLINE__ */ g();\n", "src/a.ts", /bundler/],
    // an annotation where no digest holds it: ending the line before, in an
    // empty JSX expression, on a type
    [
      'import { make } from "./make"; /*#__PURE__*/\nexport const f = make();\n',
      "src/a.ts",
      /bundler/,
    ],
    [
      "export const C = () => (\n  <div>\n    {/* @vite-ignore */}\n  </div>\n);\n",
      "src/a.tsx",
      /bundler/,
    ],
  ];
  for (const [text, path, want] of cases) assert.match(why(text, path) ?? "", want, text);
});

test("a byte order mark or a shebang keeps the file from being whole", () => {
  assert.match(why("﻿export const f = 1;\n") ?? "", /byte order mark/);
  assert.match(why("#!/usr/bin/env node\nconsole.log(1);\n", "bin/a.js") ?? "", /shebang/);
});

test("a comment anywhere is seen: inside a body, after the last statement, in JSX", () => {
  assert.match(
    why("export function f() {\n  const a = 1; /* c8 ignore next */\n  return a;\n}\n") ?? "",
    /coverage/,
  );
  assert.match(why("export const f = 1;\n/* c8 ignore stop */") ?? "", /coverage/);
  assert.match(
    why("export function f() {\n  return 1;\n  /* istanbul ignore next */\n}\n") ?? "",
    /coverage/,
  );
  assert.match(
    why(
      "export const C = () => (\n  <div>\n    {/* @refresh reset */}\n  </div>\n);\n",
      "src/a.tsx",
    ) ?? "",
    /pragma/,
  );
});

test("code no digest holds whole keeps the file from being whole", () => {
  const cases: [string, string, RegExp][] = [
    // `export` and `let` sit on the statement, each declaration is a unit
    ["export const a = 1, b = 2;\n", "src/a.ts", /several declarations/],
    ["let a = 1, b = 2;\nexport const c = () => a + b;\n", "src/a.ts", /several declarations/],
    // the call runs on load, and no unit holds it
    ["const {} = setUp();\n", "src/a.ts", /binds no name/],
    // with decorator metadata a member's types become code
    [
      "function d(..._: unknown[]) {}\nexport class A {\n  @d\n  f(x: number) { return x; }\n}\n",
      "src/a.ts",
      /decorator/,
    ],
    // what an import names, when nothing reads it, is in no digest
    ['import { a } from "./a";\nexport const f = 1;\n', "src/a.ts", /import binding .*\(a\)/],
    ['import React from "react";\nexport const f = () => <a />;\n', "src/a.tsx", /\(React\)/],
    // a build that keeps imports as written links what it names
    [
      'import { T } from "./t";\nexport const f = (x: T) => x;\n',
      "src/a.ts",
      /read only in types.*\(T\)/,
    ],
    // the build drops an abstract property and emits a plain one
    ["export abstract class A {\n  abstract x: number;\n}\n", "src/a.ts", /abstract property/],
    // how a module loads is in no digest either
    [
      'import data from "./d.json" with { type: "json" };\nexport const f = () => data;\n',
      "src/a.ts",
      /attributes/,
    ],
  ];
  for (const [text, path, want] of cases) assert.match(why(text, path) ?? "", want, text);
});

test("a change those parts make keeps every digest: why they aren't whole", () => {
  // Each pair differs observably with every digest the same; the core takes a change for
  // unobservable only when the file is whole in both trees.
  const pairs: [string, string, string][] = [
    ["export const a = 1, b = 2;\n", "const a = 1, b = 2;\n", "src/a.ts"],
    ["const {} = setUp();\n", "const {} = tearDown();\n", "src/a.ts"],
    [
      'import { a } from "./a";\nexport const f = 1;\n',
      'import { b } from "./a";\nexport const f = 1;\n',
      "src/a.ts",
    ],
    [
      'import d from "./d.json" with { type: "json" };\nexport const f = () => d;\n',
      'import d from "./d.json";\nexport const f = () => d;\n',
      "src/a.ts",
    ],
    [
      "function d(..._: unknown[]) {}\nexport class A {\n  @d\n  f(x: number) { return x; }\n}\n",
      "function d(..._: unknown[]) {}\nexport class A {\n  @d\n  f(x: string) { return x; }\n}\n",
      "src/a.ts",
    ],
    ["/*! v1 */\nexport const f = 1;\n", "/*! v2 */\nexport const f = 1;\n", "src/a.ts"],
    [
      "export abstract class A {\n  abstract x: number;\n}\n",
      "export abstract class A {\n  x: number;\n}\n",
      "src/a.ts",
    ],
    [
      'import { T } from "./t";\nexport const f = (x: T) => x;\n',
      'import { U as T } from "./t";\nexport const f = (x: T) => x;\n',
      "src/a.ts",
    ],
  ];
  for (const [a, b, path] of pairs) {
    assert.deepEqual(digests(a, path), digests(b, path), a);
    assert.ok(why(a, path) || why(b, path), a);
  }
});
